using System;
using UnityEngine;
using LWS.TruckBowling;
namespace LWS.TruckCheeseRolling.Editor {
public static class CheeseFixtures {
 public static void Run(){int n=0;Action<bool,string> check=(v,s)=>{if(!v)throw new Exception("Cheese fixture "+s);n++;};check(CheeseRules.RunoutControl(new Vector3(0,6,250))>.99f,"flat runout control enabled");check(CheeseRules.RunoutControl(new Vector3(0,100,80))<.01f,"steep hill retains chaos");check(CheeseRules.RunoutControl(new Vector3(0,20,160))<CheeseRules.RunoutControl(new Vector3(0,6,240)),"terrain grade blend");check(Mathf.Abs(CheeseRules.Height(0,-4)-CheeseRules.Height(0,8))<.001f,"level elevated starter rows");check(CheeseRules.Safe(CheeseRules.Surface(35,8,1.2f)),"high starter is inside relative-height recovery bounds");check(Mathf.Abs(CheeseRules.HillGradeScale-.875f)<.001f,"twelve-and-a-half percent gentler main grade");check(CheeseRules.Height(0,8)>280,"enormous high platform retained");for(int x=-35;x<=35;x+=10)check(Mathf.Abs(CheeseRules.Height(x,-4)-CheeseRules.Height(0,8))<.001f,"all starter slots level");float maxCross=0,maxAlong=0;for(int z=36;z<=188;z+=2)for(int x=-44;x<=44;x+=2){float h=CheeseRules.Height(x,z);check(!float.IsNaN(h)&&!float.IsInfinity(h),"finite traversable height");maxCross=Mathf.Max(maxCross,Mathf.Abs(CheeseRules.Height(x+.25f,z)-CheeseRules.Height(x-.25f,z))*2);maxAlong=Mathf.Max(maxAlong,Mathf.Abs(CheeseRules.Height(x,z+.25f)-CheeseRules.Height(x,z-.25f)) *2);}check(maxCross<.65f&&maxAlong<2.5f,"smooth bounded terrain gradients without sharp seams");check(Mathf.Abs(CheeseRules.Height(-19,73)-CheeseRules.Height(19,73))>.3f,"different natural downhill route profiles");check(CheeseRules.BackgroundCount>=12,"twelve background");check(CheeseRules.Target==5,"first five");check(CheeseRules.Resolve(0,4)==-1,"no contact");for(int i=0;i<4;i++)check(CheeseRules.Resolve(1u<<i,4)==i,"physical source "+i);check(CheeseRules.Resolve(3,4)==-2,"simultaneous neutral");check(CheeseRules.Resolve(12,4)==-2,"simultaneous high indices");check(CheeseRules.Resolve(1u<<9,4)==-1,"background cannot consume point");check(CheeseRules.Height(0,10)-CheeseRules.Height(0,130)>140,"sustained steep descent");check(CheeseRules.Height(60,180)>CheeseRules.Height(0,180)+15,"natural banks");check(Mathf.Abs(CheeseRules.Height(0,250)-CheeseRules.Height(0,280))<.01f,"broad flat mud");var s=new BowlingSetup{count=4,mode=BowlingMode.Simultaneous};check(s.Validate(out _),"default independent sources");s.players[1].source=BowlingSource.Keyboard;s.players[1].forward=s.players[0].forward;check(!s.Validate(out _),"duplicate keyboard rejected");var grid=CheeseRules.StarterGrid(8137,1);var seen=new bool[16];foreach(int slot in grid){check(slot>=0&&slot<16&&!seen[slot],"unique starter slot "+slot);seen[slot]=true;}check(CheeseRules.StarterGrid(8137,1)[0]==grid[0],"reproducible starter seed");bool changed=false,outside=false;for(int round=1;round<=24;round++){int slot=CheeseRules.StarterGrid(8137,round)[0];changed|=slot!=grid[0];outside|=slot%8==0||slot%8==7;}check(changed&&outside,"participant samples full grid including outside");var boost=new CheeseStartBoost();boost.Sample(.2f,true);boost.Sample(1.5f,true);check(!boost.Armed,"early held throttle not boosted");boost.Sample(1.6f,false);boost.Sample(1.7f,true);check(boost.Armed,"fresh throttle during two armed");boost.Sample(2.8f,true);check(boost.Armed,"hold through one retains boost");boost.Sample(2.9f,false);check(!boost.Armed,"release cancels boost");boost.Sample(2.95f,true);check(!boost.Armed,"late press rejected");Debug.Log("CHEESE_RULE_FIXTURES_PASS "+n);}
}
}
